function marketDirectory(){let rows=DB.markets.filter(m=>match(m.name+' '+(m.naic||''),S.filters.marketsQ)&&(!S.filters.marketsType||m.type===S.filters.marketsType)&&(!S.filters.marketsStatus||m.status===S.filters.marketsStatus));rows.sort((a,b)=>S.filters.marketsSort==='status'?a.status.localeCompare(b.status)||a.name.localeCompare(b.name):a.name.localeCompare(b.name));const p=paginate(rows,'markets',10);return `<div class="between sectionhead"><div><h2>Carrier/Market Management</h2><p class="subtitle">Manage carrier and MGA records, supported business and contacts.</p></div>${link('+ Add Carrier','#/admin/markets/new','btn primary')}</div><div class="toolbar">${filterSearch('marketsQ','Search carriers and markets…')}${filterSelect('marketsType',['Carrier','MGA'],'All market types')}${filterSelect('marketsStatus',['Active','Inactive','Pending'],'All statuses')}${filterSelect('marketsSort',[['name','Name A–Z'],['status','Status']],'Sort: name')}${clearTableFiltersV9('markets')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Carrier / Market</th><th>Type</th><th>NAIC code</th><th>Supported LOBs</th><th>States</th><th>Status</th><th></th></tr></thead><tbody>${p.items.map(m=>`<tr><td><b>${esc(m.name)}</b><div class="table-muted" style="margin-top:5px">${m.contacts.length} contacts</div></td><td><span style="color:${m.type==='MGA'?'#7c3aed':'inherit'}">${m.type}</span><div class="table-muted" style="margin-top:5px">${m.distribution}</div></td><td class="muted">${esc(m.naic||'Not entered')}</td><td style="min-width:210px">${m.lobs.length?lobList(m.lobs.map(l=>l.name)):'All lines'}</td><td>${m.states.join(', ')||'All states'}</td><td>${badge(m.status)}</td><td>${link('View','#/admin/markets/'+m.id,'btn small')}</td></tr>`).join('')||'<tr><td colspan="7">'+empty('No matching markets')+'</td></tr>'}</tbody></table></div>${pager(p,'markets')}</section>`;}
function submissionTable(rows,key='subs',{showAccountFilter=true}={}){rows=rows.filter(s=>match(s.name+' '+accountName(s.accountId),S.filters[key+'Q'])&&(!showAccountFilter||!S.filters[key+'Account']||s.accountId===S.filters[key+'Account'])&&filterAny(key+'Lob',s.lobs)&&filterAny(key+'Status',s.status)&&filterAny(key+'Producer',s.producer)&&(!S.filters[key+'Open']||!['Bound','Declined','Withdrawn'].includes(s.status)));rows.sort((a,b)=>S.filters[key+'Sort']==='name'?a.name.localeCompare(b.name):(b.updated||'').localeCompare(a.updated||''));const p=paginate(rows,key,12);return `<div class="toolbar" style="padding:16px">${filterSearch(key+'Q','Search submissions…')}${showAccountFilter?filterSelect(key+'Account',DB.accounts.map(a=>[a.id,a.name]),'All accounts'):''}${filterSelect(key+'Lob',LOBS,'All lines')}${filterSelect(key+'Status',STATUSES,'All statuses')}${filterSelect(key+'Producer',PRODUCERS,'All producers')}${filterSelect(key+'Sort',[['updated','Recently updated'],['name','Name A–Z']],'Sort: recently updated')}${clearTableFiltersV9(key)}${S.filters[key+'Open']?act('Open only ×','clear-open-filter',{key},'btn small'):''}</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Account</th><th>Lines of business</th><th>Effective</th><th>Submitted</th><th>Producer</th><th>CSR</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${p.items.map(s=>`<tr><td>${link(esc(s.name),subHref(s),'td-name')}</td><td>${link(esc(accountName(s.accountId)),'#/accounts/'+s.accountId)}</td><td style="min-width:190px">${lobList(s.lobs)}</td><td>${fmtDate(s.effective)}</td><td>${fmtDate(s.submitted)}</td><td>${person(s.producer)}</td><td class="nowrap">${esc(s.csr)}</td><td>${badge(s.status)}</td><td class="table-muted">${fmtDate(s.updated)}</td><td>${act(icon('more'),'submission-menu',{id:s.id},'iconbtn small')}</td></tr>`).join('')||`<tr><td colspan="10">${empty('No submissions match','Try clearing the search or filters.')}</td></tr>`}</tbody></table></div>${pager(p,'submissions')}`;}

const tableFilterKeysV9={branches:['Q','Status','Sort'],user:['Q','Status','Role','Branch','Sort'],markets:['Q','Type','Status','Sort'],homeTasks:['Q','Status','Sort'],homeSubs:['Q','Status','Sort'],subs:['Q','Account','Lob','Status','Producer','Open','Sort'],accountSubs:['Q','Lob','Status','Producer','Open','Sort']};
function clearTableFiltersV9(key,always=false){return always||(tableFilterKeysV9[key]||[]).some(k=>{const v=S.filters[key+k];return Array.isArray(v)?v.length:v;})?act('Clear filters','v9-clear-table',{key},'btn small'):'';}
const actionBeforeTablesV9=handleAction;
handleAction=async function(action,d,el){if(action==='v9-clear-table'){for(const suffix of tableFilterKeysV9[d.key]||[])delete S.filters[d.key+suffix];S.filters[d.key+'Page']=1;return render();}return actionBeforeTablesV9(action,d,el);};
